+<!doctype html>
+<html lang="en">
+<head>
+<meta charset="utf-8">
+<title>crypto-meltdown</title>
+<!-- Motion Studio, Sarcastic Grotesque: a crypto trader (vlad) watches the market dump live at 3 AM.
+     Beats: SETUP smug -> -5% fake smile -> -40% SNAP panic -> denial "buy the dip" -> -80% SNAP scream -> escalation run
+     -> Pip on a call (calm) -> "I am the dip" (calm) -> LIQUIDATED -> Pip SNAP laugh -> PUNCHLINE ECU psycho smile + meme. -->
+<style>
+@font-face{font-family:Anton;src:url(../../vendor/fonts/anton-latin-400-normal.woff2)}
+@font-face{font-family:Inter;font-weight:800;src:url(../../vendor/fonts/inter-latin-800-normal.woff2)}
+html,body{margin:0;height:100%;background:#000;overflow:hidden}
+#stage{position:absolute;left:50%;top:50%;width:1080px;height:1920px;overflow:hidden;background:#4B4760}
+svg text{font-family:Inter,sans-serif}
+</style>
+</head>
+<body>
+<div id="stage"><svg id="scene" width="1080" height="1920" viewBox="0 0 1080 1920" style="position:absolute;inset:0"></svg></div>
+<script src="../../vendor/gsap.min.js"></script>
+<script src="../../lib/bm-core.js"></script>
+<script src="../../lib/camera.js"></script>
+<script src="../../lib/styles.js"></script>
+<script src="../../lib/grotesque.js"></script>
+<script src="voice/dialog.js" onerror="window.DIALOG=null"></script>
+<script>
+Promise.all([document.fonts.load('40px Anton'), document.fonts.load('800 40px Inter')]).then(() => {
+const { GR, CAM, R, CI, EL, PA, LN, TX, G } = BM, W = 1080, H = 1920, DUR = 20, INK = '#16110E';
+BM.init({ W, H, DUR, svg: document.getElementById('scene') });
+BM.STYLE.use('grotesque');
+const FALLBACK = [
